import math

def distance(a, b):
    return math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)

def nearest_center(p, centers):
    return min(range(len(centers)), key=lambda i: distance(p, centers[i]))
points = [(1, 2), (1.5, 1.8), (2, 2.5), (2.2, 1.7), (6, 6), (6.5, 5.5), (7, 6.2), (6.8, 6.8), (3, 8), (3.5, 8.5), (4, 7.8), (4.2, 8.8)]
def mean_point(m):
    return (sum(p[0] for p in m) / len(m), sum(p[1] for p in m) / len(m))
def kmeans(centers, rounds):
    for _ in range(rounds):
        labels = [nearest_center(p, centers) for p in points]
        centers = [mean_point([p for p, l in zip(points, labels) if l == i]) for i in range(len(centers))]
    return labels, centers
def wcss(centers, labels):
    return sum(distance(p, centers[l]) ** 2 for p, l in zip(points, labels))
